import org.eclipse.swt.SWT;
import org.eclipse.swt.events.ModifyListener;
import org.eclipse.swt.layout.GridLayout;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.widgets.Text;
import org.eclipse.swt.events.ModifyEvent;

// This example requires Eclipse SWT and JFace libraries on the classpath to compile and run.
// Specifically, org.eclipse.swt.widgets.Text, org.eclipse.jface.util.BidiUtils.
public class Example {
    public static void main(String[] args) {
        Display display = new Display();
        Shell shell = new Shell(display);
        shell.setLayout(new GridLayout());

        Text fNameText = new Text(shell, SWT.BORDER);
        fNameText.setText("Name Field");
        fNameText.addModifyListener(new ModifyListener() {
            @Override
            public void modifyText(ModifyEvent e) {
                System.out.println("Name modified: " + fNameText.getText());
            }
        });

        Text fDescriptionText = new Text(shell, SWT.BORDER | SWT.MULTI);
        fDescriptionText.setText("Description Field");
        fDescriptionText.addModifyListener(new ModifyListener() {
            @Override
            public void modifyText(ModifyEvent e) {
                System.out.println("Description modified: " + fDescriptionText.getText());
            }
        });

        shell.pack();
        shell.open();
        while (!shell.isDisposed()) {
            if (!display.readAndDispatch()) {
                display.sleep();
            }
        }
        display.dispose();
    }
}

