import org.eclipse.swt.SWT;
import org.eclipse.swt.events.SelectionListener;
import org.eclipse.swt.layout.GridLayout;
import org.eclipse.swt.widgets.Button;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.widgets.Text;
import org.eclipse.swt.events.SelectionEvent;
import org.eclipse.swt.events.ModifyListener;
import org.eclipse.swt.events.ModifyEvent;

// This example requires Eclipse SWT and JFace libraries on the classpath to compile and run.
public class NegativeExample {
    public static void main(String[] args) {
        Display display = new Display();
        Shell shell = new Shell(display);
        shell.setLayout(new GridLayout());

        // This should NOT match: Button, not Text
        Button button = new Button(shell, SWT.PUSH);
        button.setText("Click Me");
        button.addSelectionListener(new SelectionListener() {
            @Override
            public void widgetSelected(SelectionEvent e) {
                System.out.println("Button clicked!");
            }
            @Override
            public void widgetDefaultSelected(SelectionEvent e) {}
        });

        // This should NOT match: A Text widget, but without an addModifyListener call
        Text onlyText = new Text(shell, SWT.BORDER);
        onlyText.setText("No listener text");

        // This should NOT match: A Text widget with a listener, but a different type of listener
        Text otherListenerText = new Text(shell, SWT.BORDER);
        otherListenerText.setText("Other listener text");
        otherListenerText.addHelpListener(e -> System.out.println("Help requested"));

        shell.pack();
        shell.open();
        while (!shell.isDisposed()) {
            if (!display.readAndDispatch()) {
                display.sleep();
            }
        }
        display.dispose();
    }
}
